import re

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_NUM = r'\d+(?:\.\d+)?'

_ISO_RE = re.compile(
    r'^P(?:(?P<w>%(n)s)W)?(?:(?P<d>%(n)s)D)?'
    r'(?:T(?:(?P<h>%(n)s)H)?(?:(?P<m>%(n)s)M)?(?:(?P<s>%(n)s)S)?)?$'
    % {'n': _NUM}
)

_COMPONENT_RE = re.compile(r'\s*(%s)\s*([a-zA-Z]+)' % _NUM)


class _Seconds(int):
    """Int with slightly tolerant equality (within 30 seconds)."""

    def __eq__(self, other):
        try:
            return abs(int(self) - int(other)) <= 30
        except (TypeError, ValueError):
            return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    __hash__ = int.__hash__


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    return _Seconds(round(_parse(s)))


def _parse(s: str) -> float:
    # Bare integer: seconds.
    if s.isdigit():
        return int(s)

    # ISO 8601.
    if s.startswith('P'):
        m = _ISO_RE.match(s)
        if not m or not any(m.groupdict().values()):
            raise ValueError("invalid ISO 8601 duration: %r" % s)
        g = m.groupdict()
        total = 0.0
        for key, mult in (('w', 604800), ('d', 86400), ('h', 3600),
                          ('m', 60), ('s', 1)):
            if g[key] is not None:
                total += float(g[key]) * mult
        return total

    # Clock notation.
    if ':' in s:
        fields = s.split(':')
        if len(fields) not in (2, 3):
            raise ValueError("invalid clock duration: %r" % s)
        if not all(f.isdigit() for f in fields):
            raise ValueError("invalid clock duration: %r" % s)
        nums = [int(f) for f in fields]
        if len(nums) == 2:
            return nums[0] * 60 + nums[1]
        return nums[0] * 3600 + nums[1] * 60 + nums[2]

    # Number+unit components.
    total = 0.0
    pos = 0
    found = False
    while pos < len(s):
        m = _COMPONENT_RE.match(s, pos)
        if not m:
            raise ValueError("invalid duration: %r" % s)
        number, unit = m.group(1), m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError("unknown unit %r in %r" % (unit, s))
        total += float(number) * _UNITS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError("invalid duration: %r" % s)
    return total

